import Quartz
import AppKit
import Foundation

// Find the Simulator window
let windows = CGWindowListCopyWindowInfo([.excludeDesktopElements], kCGNullWindowID) as? [[String: Any]] ?? []

var simulatorWindow: [String: Any]?
for window in windows {
    if let name = window[kCGWindowName as String] as? String, 
       name.contains("Simulator") || name.contains("iPhone") {
        simulatorWindow = window
        print("Found simulator window: \(name)")
